const MARK = /provisional|pending|placeholder|audit-allow/i;
function strip(line, state){let r='',i=0;while(i<line.length){if(state.inBlockComment){const e=line.indexOf('*/',i);if(e===-1)return r;i=e+2;state.inBlockComment=false;continue;}if(line[i]==='/'&&line[i+1]==='/'&&line[i-1]!==':')break;if(line[i]==='/'&&line[i+1]==='*'){state.inBlockComment=true;i+=2;continue;}r+=line[i];i+=1;}return r;}
